const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quote = (items: Item[]): QuoteResult => {
  const policyBase = sumBasePremiums(items);

  return {
    premium: policyBase * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE,
  };
};

